package br.com.gestao.sale; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="sales") public class Sale{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String customerName; private String createdBy; @Column(nullable=false) private LocalDateTime createdAt; @Column(nullable=false,precision=12,scale=2) private BigDecimal total; @OneToMany(mappedBy="sale",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) private List<SaleItem> items=new ArrayList<>(); public Sale(){} public Sale(String customerName,String createdBy){this.customerName=customerName;this.createdBy=createdBy;this.createdAt=LocalDateTime.now();this.total=BigDecimal.ZERO;} public void addItem(SaleItem i){i.setSale(this);items.add(i);total=total.add(i.getSubtotal());} public Long getId(){return id;} public String getCustomerName(){return customerName;} public String getCreatedBy(){return createdBy;} public LocalDateTime getCreatedAt(){return createdAt;} public BigDecimal getTotal(){return total;} public List<SaleItem> getItems(){return items;}}
